package urchart.assistant;
import java.util.*;
/** Small dependency-free JSON reader/writer for the assistant module. */
public final class Json {
  private final String s; private int p;
  private Json(String s){this.s=s;}
  public static Object parse(String s){Json j=new Json(s);Object v=j.value();j.ws();if(j.p!=s.length())throw new IllegalArgumentException("Invalid JSON");return v;}
  @SuppressWarnings("unchecked") public static Map<String,Object> object(String s){Object v=parse(s);if(!(v instanceof Map))throw new IllegalArgumentException("Expected JSON object");return (Map<String,Object>)v;}
  public static String str(Object x){return x==null?"":String.valueOf(x);}
  public static String stringify(Object v){if(v==null)return "null";if(v instanceof String t)return quote(t);if(v instanceof Number||v instanceof Boolean)return v.toString();if(v instanceof Map<?,?> m){List<String> p=new ArrayList<>();for(var e:m.entrySet())p.add(quote(String.valueOf(e.getKey()))+":"+stringify(e.getValue()));return "{"+String.join(",",p)+"}";}if(v instanceof Iterable<?> it){List<String> p=new ArrayList<>();for(Object x:it)p.add(stringify(x));return "["+String.join(",",p)+"]";}throw new IllegalArgumentException("Unsupported JSON type");}
  public static String quote(String s){StringBuilder b=new StringBuilder("\"");for(char c:s.toCharArray()){switch(c){case '\\'->b.append("\\\\");case '"'->b.append("\\\"");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}}return b.append('"').toString();}
  private void ws(){while(p<s.length()&&Character.isWhitespace(s.charAt(p)))p++;}
  private char next(){if(p>=s.length())throw new IllegalArgumentException("Unexpected end of JSON");return s.charAt(p++);}
  private Object value(){ws();if(p>=s.length())throw new IllegalArgumentException("Missing value");char c=s.charAt(p);if(c=='"')return string();if(c=='{')return map();if(c=='[')return array();if(s.startsWith("true",p)){p+=4;return true;}if(s.startsWith("false",p)){p+=5;return false;}if(s.startsWith("null",p)){p+=4;return null;}int start=p;if(c=='-')p++;while(p<s.length()&&Character.isDigit(s.charAt(p)))p++;if(p<s.length()&&s.charAt(p)=='.'){p++;while(p<s.length()&&Character.isDigit(s.charAt(p)))p++;}if(p<s.length()&&(s.charAt(p)=='e'||s.charAt(p)=='E')){p++;if(p<s.length()&&(s.charAt(p)=='+'||s.charAt(p)=='-'))p++;while(p<s.length()&&Character.isDigit(s.charAt(p)))p++;}if(p==start)throw new IllegalArgumentException("Invalid JSON token");return Double.valueOf(s.substring(start,p));}
  private String string(){next();StringBuilder b=new StringBuilder();while(true){char c=next();if(c=='"')return b.toString();if(c=='\\'){char e=next();switch(e){case 'n'->b.append('\n');case 'r'->b.append('\r');case 't'->b.append('\t');case 'b'->b.append('\b');case 'f'->b.append('\f');case '"'->b.append('"');case '\\'->b.append('\\');case '/'->b.append('/');case 'u'->{if(p+4>s.length())throw new IllegalArgumentException("Bad unicode escape");b.append((char)Integer.parseInt(s.substring(p,p+4),16));p+=4;}default->throw new IllegalArgumentException("Invalid escape");}}else{if(c<32)throw new IllegalArgumentException("Control character in string");b.append(c);}}}
  private Map<String,Object> map(){next();Map<String,Object> m=new LinkedHashMap<>();ws();if(s.charAt(p)=='}'){p++;return m;}while(true){ws();if(next()!='"')throw new IllegalArgumentException("Expected key");p--;String k=string();ws();if(next()!=':')throw new IllegalArgumentException("Expected colon");m.put(k,value());ws();char c=next();if(c=='}')return m;if(c!=',')throw new IllegalArgumentException("Expected comma");}}
  private List<Object> array(){next();List<Object>a=new ArrayList<>();ws();if(s.charAt(p)==']'){p++;return a;}while(true){a.add(value());ws();char c=next();if(c==']')return a;if(c!=',')throw new IllegalArgumentException("Expected comma");}}
}
